package main

import (
	"context"
	"errors"
	"log/slog"
	"time"

	"github.com/nats-io/nats.go"
	"go.opentelemetry.io/otel/attribute"
	"go.opentelemetry.io/otel/trace"

	"github.com/entirehq/mirror-pipeline/pkg/fanoutengine"
	"github.com/entirehq/mirror-pipeline/pkg/webhookdlq"
	"github.com/entirehq/mirror-pipeline/pkg/webhookevents"
)

// Retry envelope, mirroring cmd/meta-fanout: a flat NakWithDelay redelivery (no
// escalating BackOff) bounded by MaxDeliver, with a short AckWait backstop for a
// pod that dies mid-dispatch. push-author dispatch (unmarshal → dedupe → route →
// publish) is sub-second, so the short windows are safe. These live here (not in
// pkg/fanoutengine) because the dedup-window invariant they must satisfy is
// specific to the github_push_author_v1 stream — see TestConsumerRetryModel.
const (
	// consumerFailureDelay is the flat delay between redeliveries on a transient
	// failure (requested via NakWithDelay; a bare Nak redelivers immediately).
	consumerFailureDelay = 30 * time.Second

	// consumerMaxDeliver bounds redelivery: first attempt + 7 retries. On
	// exhaustion the engine captures the delivery to webhooks_github_dlq and
	// Terms it (when DLQ capture is wired — see dlqSink), so a Core-lookup or
	// downstream-NATS outage outlasting the redelivery span doesn't silently
	// drop push-author deliveries; matches cmd/fanout.
	//
	// Total redelivery span ((consumerMaxDeliver-1) * consumerFailureDelay) MUST
	// stay < the github_push_author_v1 duplicateWindow (5m, fleet
	// apps/nats-streams/base/github-push-author-v1.yaml); exceeding it makes
	// post-partial-failure re-publishes stop being deduped. (7 * 30s = 3m30s,
	// inside 5m.) See TestConsumerRetryModel.
	consumerMaxDeliver = 8

	// consumerAckWait is the redelivery backstop when a pod dies mid-dispatch
	// without responding (no Ack/Nak/Term).
	consumerAckWait = 30 * time.Second

	// consumerInactiveThreshold lets the SERVER reap this durable after 72h
	// without a pull request. webhooks_github_v1 is interest-retention: an
	// abandoned durable pins every subsequent delivery for ALL consumers
	// until the stream's maxAge/maxBytes wall — the 2026-06-01 incident.
	// 72h sits under the stream's 96h maxAge; an app deliberately down
	// longer loses its cursor and re-consumes what is still retained on
	// return. See fanoutengine.Config.InactiveThreshold.
	consumerInactiveThreshold = 72 * time.Hour
)

const tracerName = "core-fanout"

// newConsumer wires the push-author dispatcher into the shared fanoutengine
// runtime: the consumer scaffold (subscribe/backoff loop, Ack/Nak/Term decision
// tree, panic recovery, DLQ capture, OTel span + trace propagation) lives in the
// engine; the envelope decode, span attrs, nak classification, metrics, and DLQ
// sink are plugged in here. js may be nil when only Dispatch is exercised
// (tests); dlq is a nil interface when capture is disabled.
func newConsumer(js nats.JetStreamContext, resolver *pushAuthorResolver, regions fanoutengine.Regions, metrics *coreFanoutMetrics, durable string, dlq fanoutengine.DLQ) *fanoutengine.Consumer {
	return fanoutengine.New(js, webhookDecoder{}, resolver, regions, hooksFor(metrics), fanoutengine.Config{
		Subject:           pushFilterSubject,
		Stream:            webhookevents.StreamName,
		Durable:           durable,
		Tracer:            tracerName,
		SpanName:          "core_fanout.dispatch", // preserve the existing span name (underscore) verbatim
		AckWait:           consumerAckWait,
		MaxDeliver:        consumerMaxDeliver,
		NakDelay:          consumerFailureDelay,
		InactiveThreshold: consumerInactiveThreshold,
		ClassifyNak:       classifyNak,
		SpanAttrs:         stampGithubSpanAttrs,
		DLQ:               dlq,
	})
}

// dlqSink adapts a webhooks_github_dlq publisher to the engine's DLQ interface.
// The engine's reason strings are the same values as webhookdlq's Reason* consts
// (bad_envelope / input_error / max_deliveries), so they pass through verbatim.
type dlqSink struct{ pub *webhookdlq.Publisher }

func (s dlqSink) Capture(ctx context.Context, dl fanoutengine.DeadLetter) error {
	rec := webhookdlq.DeadLetter{
		Source:          webhookdlq.SourceCoreFanout,
		Reason:          dl.Reason,
		OriginalSubject: dl.Subject,
		DeliveryID:      dl.DeliveryID,
		Event:           dl.Event,
		Deliveries:      dl.Deliveries,
		Envelope:        dl.Envelope,
		DeadLetteredAt:  time.Now(),
	}
	if dl.Err != nil {
		rec.LastError = dl.Err.Error()
	}
	return s.pub.Publish(ctx, rec)
}

// webhookDecoder turns the raw delivery into the engine envelope by unmarshaling
// the ForwardedWebhook contract. A decode failure → Term (bad envelope).
type webhookDecoder struct{}

func (webhookDecoder) Decode(data []byte) (fanoutengine.Envelope, error) {
	fw, err := webhookevents.Unmarshal(data)
	if err != nil {
		return fanoutengine.Envelope{}, err
	}
	return fanoutengine.Envelope{
		Event:      fw.Event,
		DeliveryID: fw.DeliveryID,
		ObservedAt: fw.ReceivedAt,
		Body:       fw.Body,
	}, nil
}

// stampGithubSpanAttrs preserves the github.* span attributes the consumer used
// to set inline, kept on the domain side so the engine stays envelope-agnostic.
func stampGithubSpanAttrs(span trace.Span, env fanoutengine.Envelope) {
	span.SetAttributes(
		attribute.String("github.delivery_id", env.DeliveryID),
		attribute.String("github.event", env.Event),
	)
}

// classifyNak refines a transient (nak) error into a metric reason. An unmapped
// cluster_id (Core resolved a cell absent from FANOUT_NATS_REGIONS) is NOT
// transient — it Naks identically but never self-heals, so unless fixed it
// exhausts MaxDeliver and is dead-lettered (or final-Naks and ages out when DLQ
// capture is off) while looking like a region bounce. Surface it distinctly so
// it pages as a misconfig. The disposition stays a Nak (handled by the engine):
// the delivery may carry other healthy placements that should keep retrying,
// and a config fix within the redelivery window lets it drain.
func classifyNak(ctx context.Context, span trace.Span, err error) string {
	if errors.Is(err, fanoutengine.ErrUnmappedRegion) {
		span.SetAttributes(attribute.Bool("entire.mirror.unmapped_cluster", true))
		slog.ErrorContext(ctx, "Push-author placement routed to an unmapped cluster_id; fix FANOUT_NATS_REGIONS within the redelivery span or its deliveries dead-letter (or age out when DLQ capture is off)",
			slog.Any("error", err))
		return nakReasonUnmappedCluster
	}
	return ""
}

// hooksFor adapts the (nil-safe) metric methods into engine hooks.
func hooksFor(m *coreFanoutMetrics) fanoutengine.Hooks {
	return fanoutengine.Hooks{
		RecordDispatch: m.recordDispatch,
		RecordPanic:    m.recordPanic,
	}
}
