	// deferred nc.Close() pulls the connection out from under them. Bounded so a
	// wedged Fetch/publish can't block exit. Consumers not started in this mode
	// (nil done channel — the webhook/backfill/pr-backfill trio in lifecycle-only
	// mode) are skipped; a receive on a nil channel blocks forever and would
	// otherwise burn the full drain timeout per skipped consumer.
	for _, c := range []struct {
		name string
		done chan struct{}
	}{{"webhook", consumerDone}, {"backfill", backfillDone}, {"pr-backfill", prBackfillDone}, {"lifecycle", lifecycleDone}} {
		if c.done == nil {
			continue
		}
		select {
		case <-c.done:
		case <-time.After(consumerDrainTimeout):
			slog.Warn("Consumer drain timed out on shutdown; in-flight message may be redelivered",
				slog.String("consumer", c.name))
		}
	}
	return nil
}

// natsHealth is the local-NATS readiness check the gate consults (satisfied by
// *natsregions.Health). readySubscriber is a consumer's pull-subscription
// readiness (satisfied by *fanoutengine.Consumer and *lifecycleConsumer). Both
// are interfaces so readinessGate is unit-testable without a live NATS.
type natsHealth interface {
	Status() (bool, string)
}

type readySubscriber interface {
	Ready() bool
}

// readinessGate builds the /readyz probe. Beyond local NATS health it gates on
// the consumer this deployment actually drives: in lifecycle-only mode the
// cross-region lifecycle fan (the webhook consumer isn't started, so `webhook`
// is a nil pointer here and is never consulted); in US/default mode the live
// webhook consumer (the backfill/PR-backfill/lifecycle consumers deliberately
// don't gate — each self-heals via its own subscribe-retry loop). Extracted from
// run() so the mode-dependent gating is testable in isolation.
func readinessGate(lifecycleOnly bool, health natsHealth, webhook, lifecycle readySubscriber) svchttp.ReadyFunc {
	return func() (bool, string) {
		if ok, reason := health.Status(); !ok {
			return false, reason
		}
		if lifecycleOnly {
			if !lifecycle.Ready() {
				return false, "lifecycle consumer not subscribed"
			}
			return true, ""
		}
		if !webhook.Ready() {
			return false, "consumer not subscribed"
		}
		return true, ""
	}
}

