// Package astwalk parses every Go source file in the module for the
// convention tests that police slog usage (internal/slogutil,
// internal/natslog). Those tests share the same notion of which files a
// module-wide convention applies to; keeping it in one place means a new
// generated-code directory is excluded from all of them at once instead of
// each test's skip list drifting on its own.
package astwalk

import (
	"go/ast"
	"go/parser"
	"go/token"
	"io/fs"
	"path/filepath"
	"strings"
)

// skipDirs are trees no convention test polices: not our code to fix (vendor,
// node_modules), not handwritten (gen), not Go (.git).
var skipDirs = map[string]bool{
	"vendor":       true,
	"gen":          true,
	".git":         true,
	"node_modules": true,
}

// ModuleGoFiles parses every Go file under root (the module root — typically
// filepath.Join("..", "..") from an internal test package) with mode, calling
// visit for each. Files that fail to parse are skipped: policing syntax is
// the compiler's job, not a convention test's.
func ModuleGoFiles(root string, fset *token.FileSet, mode parser.Mode, visit func(path string, file *ast.File)) error {
	return filepath.WalkDir(root, func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if d.IsDir() {
			if skipDirs[d.Name()] {
				return filepath.SkipDir
			}
			return nil
		}
		if !strings.HasSuffix(path, ".go") {
			return nil
		}
		file, parseErr := parser.ParseFile(fset, path, nil, mode)
		if parseErr != nil {
			return nil
		}
		visit(path, file)
		return nil
	})
}
