func testStream() jetstream.StreamConfig {
	return jetstream.StreamConfig{Name: "harness", Subjects: []string{"harness.>"}}
}

// TestVersionAttribution pins that the linked server's version and the version it
// stamps into consumer metadata agree, so [natstest.Version] means something when
// a broker-semantic test fails and names it.
//
// It asserts consistency, not a literal version: pinning the number here would
// turn every deliberate bump into a spurious failure, when the point of a bump is
// to re-run the suites and see which beliefs still hold.
func TestVersionAttribution(t *testing.T) {
	t.Parallel()
	_, js := natstest.Env(t, testStream())
	cons := natstest.Consumer(t, js, "harness", jetstream.ConsumerConfig{
		Durable:   "version_probe",
		AckPolicy: jetstream.AckExplicitPolicy,
	})
	got := natstest.Info(t, cons).Config.Metadata["_nats.ver"]
	t.Logf("embedded nats-server VERSION=%s, consumer metadata _nats.ver=%s", natstest.Version(), got)
	if got == "" {
		t.Fatal("consumer metadata carries no _nats.ver; measurements taken through this harness cannot be attributed to a server version")
	}
	if got != natstest.Version() {
		t.Errorf("linked server VERSION %q and consumer metadata _nats.ver %q disagree; "+
			"measurements through this harness cannot be attributed to a single version", natstest.Version(), got)
	}
}

// TestBothHandlesDriveTheSameBroker is the property every migration trail depends
// on: the legacy nats.JetStreamContext loop and the modern jetstream loop can be
// measured against ONE broker, in one test, so a before/after pair is a
// comparison rather than two unrelated assertions.
func TestBothHandlesDriveTheSameBroker(t *testing.T) {
	t.Parallel()
	nc, _ := natstest.Connect(t, natstest.Server(t))
	modern := natstest.JetStream(t, nc)
	natstest.Stream(t, modern, testStream())
	natstest.Publish(t, modern, "harness.one", "a", "b")

	// Legacy: the shape every mirror-pipeline loop uses today.
	legacy := natstest.LegacyJetStream(t, nc)
	sub, err := legacy.PullSubscribe("harness.>", "legacy_durable",
		nats.ManualAck(), nats.AckWait(2*time.Second), nats.MaxDeliver(3))
	if err != nil {
		t.Fatalf("legacy PullSubscribe: %v", err)
	}
	msgs, err := sub.Fetch(1, nats.MaxWait(2*time.Second))
	if err != nil {
		t.Fatalf("legacy Fetch: %v", err)
	}
	if len(msgs) != 1 || string(msgs[0].Data) != "a" {
		t.Fatalf("legacy Fetch returned %d messages, want the first publish", len(msgs))
	}
	if err := msgs[0].Ack(); err != nil {
		t.Fatalf("legacy Ack: %v", err)
	}

	// Modern: the shape a migrated loop uses. Its own durable, so the two
	// cursors don't interfere.
	cons := natstest.Consumer(t, modern, "harness", jetstream.ConsumerConfig{
		Durable:       "modern_durable",
		AckPolicy:     jetstream.AckExplicitPolicy,
		AckWait:       2 * time.Second,
		MaxDeliver:    3,
		FilterSubject: "harness.>",
