		t.Fatalf("stored AckWait is the requested %s: this server does not normalize AckWait to BackOff[0], "+
			"so the constraint cmd/worker's client-ladder exception rests on does not hold on nats-server %s — "+
			"re-decide the exception recorded on COR-1254 rather than adjusting this test",
			requestedAckWait, natstest.Version())
	}
	if stored != backOff[0] {
		t.Errorf("stored AckWait = %s, want BackOff[0] = %s (requested %s) on nats-server %s",
			stored, backOff[0], requestedAckWait, natstest.Version())
	}
}

// TestNoProductionImport enforces the rule in this package's doc: importing it
// links a whole nats-server into the binary, so only _test.go files may.
//
// A convention test rather than review, because the failure is invisible at the
// call site — the import compiles, the tests pass, and the cost shows up as
// binary size and dependency surface in a container nobody re-measures.
func TestNoProductionImport(t *testing.T) {
	t.Parallel()
	moduleRoot := filepath.Join("..", "..")
	fset := token.NewFileSet()
	var offenders []string

	err := astwalk.ModuleGoFiles(moduleRoot, fset, parser.ImportsOnly, func(path string, file *ast.File) {
		if strings.HasSuffix(path, "_test.go") {
			return
		}
		for _, spec := range file.Imports {
			imported, uerr := strconv.Unquote(spec.Path.Value)
			if uerr != nil {
				continue
			}
			if imported == natstestPkg {
				offenders = append(offenders, path)
			}
		}
	})
	if err != nil {
		t.Fatalf("walk module: %v", err)
	}
	if len(offenders) > 0 {
		t.Errorf("non-test files import %s, which links an embedded nats-server into the binary: %v",
			natstestPkg, offenders)
	}
}

// Package timingcontract states a consume loop's redelivery timing as data, and
// checks it with go-nuts' exported arithmetic rather than by hand.
//
// # Why the arithmetic is not restated here
//
// ENT-1535 was a consumer whose real redelivery envelope was 34h22m while its
// config advertised 17h45m, and duplicated timing arithmetic is exactly how that
// happens: one number in a comment, another in a config, a third in a runbook,
// and nothing forcing them to agree. [jsconsumer.Schedule] is the single
// implementation — the same function go-nuts runs at consumer construction and
// fleet CI runs over a rendered Consumer CR — so everything below delegates to
// it and adds only a name and a renderer.
//
// A loop states its contract once, next to the constants it is derived from, and
// its test calls [Contract.Validate]. Two loops in this repo cannot be validated
// by jsconsumer.Start itself — cmd/worker and the meta-fanout lifecycle fan carry
// neither a server ladder nor a Retry, so Start's schedule check does not run for
// them — which is precisely why the check has to be reachable from a test.
//
// # The table is generated, not typed
//
// Every Track D migration trail carries a before/after timing table: the old
// effective ladder against the new one. [Markdown] renders it from the same
// Schedule values the test validates, so the table in the trail body cannot drift
// from the ladder in the code. Print it from a test and paste the output.
//
// This package is deliberately pure: no testing import, no NATS connection, no
// clock. It is safe to reference from production code — though today nothing
// does, and a loop that wants its contract at runtime should prefer failing at
// startup through jsconsumer.Start.
package timingcontract

import (
	"fmt"
	"strings"
	"time"

	"github.com/entireio/go-nuts/jsconsumer"
)

// Contract is one consumer's redelivery timing, named so a violation and a table
// row say which loop they are about.
type Contract struct {
	// Name identifies the loop — the durable is the clearest choice, since that
	// is what an operator reads in consumer info and in a KEDA scaler.
	Name string
	// Schedule is the timing itself. Populate it from the loop's real constants,
	// never from literals retyped alongside them: a contract that drifts from the
	// code it describes is the defect this package exists to prevent.
	Schedule jsconsumer.Schedule
}

// Validate reports every way the contract does not hang together, or nil when it
// is coherent. The violations come from [jsconsumer.Schedule.Validate]; only the
// name is added.
func (c Contract) Validate() error {
	if err := c.Schedule.Err(); err != nil {
		return fmt.Errorf("%s: %w", c.Name, err)
	}
	return nil
}

// Envelope is the handful of derived numbers a trail, a runbook, and a monitor
// all quote. Pin them in a test so a ladder change that moves any of them has to
// move the documented value with it.
type Envelope struct {
	// DeadLetterDelivery is the delivery on which the terminal branch runs —
	// MaxDeliver less any capture reserve. For a loop with no Retry this is just
	// the delivery on which the loop gives up.
	DeadLetterDelivery int
	// TimeToDeadLetter is the cumulative SCHEDULED wait before that delivery.
	// Handler time and a lost delivery's AckWait sit on top of it, so a loop
	// whose handler runs for minutes has a real envelope far longer than this
	// number — cmd/worker is the worked example, and its own test pins the
	// wall-clock bound separately against the stream's max age.
	TimeToDeadLetter time.Duration
	// LongestRung is the largest single wait served before the terminal branch.
	LongestRung time.Duration
}

// Envelope computes the contract's derived numbers.
func (c Contract) Envelope() Envelope {
	return Envelope{
		DeadLetterDelivery: c.Schedule.DeadLetterDelivery(),
		TimeToDeadLetter:   c.Schedule.TimeToDeadLetter(),
		LongestRung:        c.Schedule.LongestRung(),
	}
}

// CheckEnvelope reports how the contract's derived numbers differ from want, or
// nil when they match. Use it to pin the figures a trail or a monitor quotes.
func (c Contract) CheckEnvelope(want Envelope) error {
	got := c.Envelope()
	var diffs []string
	if got.DeadLetterDelivery != want.DeadLetterDelivery {
		diffs = append(diffs, fmt.Sprintf("dead-letter delivery %d, want %d", got.DeadLetterDelivery, want.DeadLetterDelivery))
	}
	if got.TimeToDeadLetter != want.TimeToDeadLetter {
		diffs = append(diffs, fmt.Sprintf("time to dead-letter %s, want %s", got.TimeToDeadLetter, want.TimeToDeadLetter))
	}
	if got.LongestRung != want.LongestRung {
		diffs = append(diffs, fmt.Sprintf("longest rung %s, want %s", got.LongestRung, want.LongestRung))
	}
	if len(diffs) == 0 {
		return nil
	}
	return fmt.Errorf("%s: %s", c.Name, strings.Join(diffs, "; "))
}

// Markdown renders the delivery-by-delivery table a migration trail carries: one
// row per delivery, one column per contract, each cell the cumulative scheduled
// wait by which that delivery arrives. Pass the before and after contracts
// together to get the comparison in a single table.
//
// A contract with unlimited redeliveries has no terminal branch and therefore no
// table; it renders as a note instead, since a row count would be a fiction.
func Markdown(contracts ...Contract) string {
	if len(contracts) == 0 {
		return ""
	}

	var b strings.Builder
	rows := 0
	for _, c := range contracts {
		if c.Schedule.MaxDeliver > rows {
			rows = c.Schedule.MaxDeliver
		}
	}
	if rows <= 0 {
		for _, c := range contracts {
			fmt.Fprintf(&b, "- %s: unlimited redeliveries — no terminal branch, so no envelope to table.\n", c.Name)
		}
		return b.String()
	}

	b.WriteString("| delivery |")
	for _, c := range contracts {
		fmt.Fprintf(&b, " %s |", c.Name)
	}
	b.WriteString("\n|---:|")
	for range contracts {
		b.WriteString("---|")
	}
	b.WriteString("\n")

	for n := 1; n <= rows; n++ {
		fmt.Fprintf(&b, "| %d |", n)
		for _, c := range contracts {
			b.WriteString(" " + cell(c, n) + " |")
		}
		b.WriteString("\n")
	}

	b.WriteString("\n")
	for _, c := range contracts {
		e := c.Envelope()
		fmt.Fprintf(&b, "- **%s** — gives up on delivery %d at %s; longest rung %s",
			c.Name, e.DeadLetterDelivery, e.TimeToDeadLetter, e.LongestRung)
		if c.Schedule.StreamMaxAge > 0 {
			fmt.Fprintf(&b, "; stream discards after %s", c.Schedule.StreamMaxAge)
		}
		b.WriteString(".\n")
	}
	return b.String()
}

// cell renders one contract's entry for delivery n: when it arrives, and what
// happens on it. A delivery past this contract's cap is blank rather than zero —
// the two schedules being compared often have different caps, and a "0s" there
// reads as an instant retry.
func cell(c Contract, n int) string {
	if c.Schedule.MaxDeliver > 0 && n > c.Schedule.MaxDeliver {
		return ""
	}
	at := "t+" + c.Schedule.CumulativeTo(n).String()
	switch {
	case n == c.Schedule.DeadLetterDelivery():
		return at + " — give up"
	case c.Schedule.RecoverBy > 0 && n == c.Schedule.RecoverBy:
		return at + " — RecoverBy"
	case c.Schedule.MaxDeliver > 0 && n > c.Schedule.DeadLetterDelivery():
		return at + " — capture reserve"
	default:
		return at
	}
}

package timingcontract_test

import (
	"strings"
	"testing"
	"time"

	"github.com/entireio/go-nuts/jsconsumer"

	"github.com/entirehq/mirror-pipeline/internal/timingcontract"
)

// TestValidateRejectsMixedOwnership pins the ENT-1535 defect detector: a
// client-side NakDelay AND a server-side BackOff on one consumer. The server
// stretches each NAK delay by the BackOff increments, so redeliveries follow
// neither ladder while the configured one still reads as authoritative.
//
// This is the check every Track D migration has to keep passing, because the
// migration's whole shape — some loops keep a client ladder, some move to a
// server one — is one edit away from producing exactly this.
func TestValidateRejectsMixedOwnership(t *testing.T) {
	t.Parallel()
	c := timingcontract.Contract{
		Name: "mixed",
		Schedule: jsconsumer.Schedule{
			NakDelay:      30 * time.Second,
			ServerBackOff: []time.Duration{30 * time.Second, 60 * time.Second},
			MaxDeliver:    8,
			AckWait:       30 * time.Second,
		},
	}
	err := c.Validate()
	if err == nil {
		t.Fatal("a client NakDelay alongside a server BackOff validated clean; the ENT-1535 detector is not running")
	}
	if !strings.Contains(err.Error(), "mixed") {
		t.Errorf("violation does not name the contract: %v", err)
	}
}

// TestValidateRejectsAckWaitDisagreeingWithFirstRung pins the other arithmetic
// trap the adoption guidance calls out: with a ladder set, the server stores
// BackOff[0] in place of the declared AckWait, so a mismatch is config that never
// runs — and a pedantic-mode create rejects it outright rather than rewriting it.
//
// natstest.REDACTED measures the same fact
// against a real broker; this asserts the library catches it before a consumer
// ever starts.
func TestValidateRejectsAckWaitDisagreeingWithFirstRung(t *testing.T) {
	t.Parallel()
	c := timingcontract.Contract{
		Name: "skewed",
		Schedule: jsconsumer.Schedule{
			ServerBackOff: []time.Duration{30 * time.Second},
			MaxDeliver:    8,
			AckWait:       31 * time.Second, // one second off, and therefore dead config
		},
	}
	if err := c.Validate(); err == nil {
		t.Fatal("AckWait disagreeing with ServerBackOff[0] validated clean")
	}
}

// TestClientScheduledFlatLadderIsCoherent pins that a SINGLE-owner client ladder
// — no server BackOff — is a valid configuration, not a violation.
//
// This is the shape cmd/worker keeps (COR-1254 records it as a class rule: a
// consumer whose handler time vastly exceeds its desired first rung cannot use a
// server ladder, because AckWait is normalized to BackOff[0]). The distinction
// that makes it legal is ownership, not mechanism: ENT-1535 was MIXED ownership,
// which TestValidateRejectsMixedOwnership above still rejects.
//
// The AckWait here is 15m against a 30s rung deliberately: under a server ladder
// that pair is a violation, and this case would fail if the check stopped
// distinguishing who owns the schedule.
func TestClientScheduledFlatLadderIsCoherent(t *testing.T) {
	t.Parallel()
	c := timingcontract.Contract{
		Name: "mirror-git-v1-<jur>-<cluster>",
		Schedule: jsconsumer.Schedule{
			NakDelay:     30 * time.Second,
			MaxDeliver:   10,
			AckWait:      15 * time.Minute,
			StreamMaxAge: 6 * time.Hour,
		},
	}
	if err := c.Validate(); err != nil {
		t.Fatalf("single-owner client ladder rejected: %v", err)
	}
	if err := c.CheckEnvelope(timingcontract.Envelope{
		DeadLetterDelivery: 10,
		TimeToDeadLetter:   4*time.Minute + 30*time.Second, // 9 redeliveries x 30s
		LongestRung:        30 * time.Second,
	}); err != nil {
		t.Error(err)
	}
}

// TestValidateRejectsALadderOutlivingRetention pins the loss class ENT-1492 is
// about: a ladder that takes longer than the stream keeps the message never
// reaches its own terminal branch, because the stream discards it first.
//
// Kept here rather than left to go-nuts because it is the check most likely to
// start mattering during this migration: three of the four loops sit on streams
// whose max age a fleet overlay can shorten per cell.
func TestValidateRejectsALadderOutlivingRetention(t *testing.T) {
	t.Parallel()
	c := timingcontract.Contract{
		Name: "outlives-retention",
		Schedule: jsconsumer.Schedule{
			ServerBackOff: []time.Duration{time.Hour},
			MaxDeliver:    8,
			AckWait:       time.Hour,
			StreamMaxAge:  2 * time.Hour, // 7 x 1h of ladder against 2h of retention
		},
	}
	if err := c.Validate(); err == nil {
		t.Fatal("a ladder outliving the stream's retention validated clean")
	}
}

// TestMarkdownRendersTheBeforeAfterComparison exercises the renderer on the exact
// shape loop 2 (webhook-forwarder) will carry, so the table format is proven
// before a trail depends on it: a flat client ladder today, a server-owned ladder
// with one capture reserve after, with the give-up delivery and its timing
// preserved byte-for-byte.
func TestMarkdownRendersTheBeforeAfterComparison(t *testing.T) {
	t.Parallel()
	before := timingcontract.Contract{
		Name: "before (client Nak)",
		Schedule: jsconsumer.Schedule{
			NakDelay:   30 * time.Second,
			MaxDeliver: 8,
			AckWait:    30 * time.Second,
		},
	}
	after := timingcontract.Contract{
		Name: "after (server ladder)",
		Schedule: jsconsumer.Schedule{
			ServerBackOff:  flat(30*time.Second, 8),
			MaxDeliver:     9,
			AckWait:        30 * time.Second,
			CaptureReserve: 1,
		},
	}
	for _, c := range []timingcontract.Contract{before, after} {
		if err := c.Validate(); err != nil {
			t.Fatalf("%s: %v", c.Name, err)
		}
	}

	// The property the migration promises: same give-up delivery, same wait.
	wantEnvelope := timingcontract.Envelope{
		DeadLetterDelivery: 8,
		TimeToDeadLetter:   3*time.Minute + 30*time.Second,
		LongestRung:        30 * time.Second,
	}
	for _, c := range []timingcontract.Contract{before, after} {
		if err := c.CheckEnvelope(wantEnvelope); err != nil {
			t.Error(err)
		}
	}

	out := timingcontract.Markdown(before, after)
	t.Logf("rendered timing contract:\n%s", out)

	for _, want := range []string{
		"| delivery |",
		"before (client Nak)",
		"after (server ladder)",
		"t+3m30s — give up",
		"t+4m0s — capture reserve",
	} {
		if !strings.Contains(out, want) {
			t.Errorf("rendered table is missing %q:\n%s", want, out)
		}
	}
	// The before contract stops at 8 deliveries; its 9th cell must be blank
	// rather than a zero that would read as an instant retry.
	lines := strings.Split(out, "\n")
	var ninth string
	for _, l := range lines {
		if strings.HasPrefix(l, "| 9 |") {
			ninth = l
		}
	}
	if ninth == "" {
		t.Fatalf("no row for delivery 9:\n%s", out)
	}
	if strings.Contains(ninth, "t+") && strings.Count(ninth, "t+") != 1 {
		t.Errorf("delivery 9 should have a timing only for the after contract, got: %s", ninth)
	}
}

// TestMarkdownHandlesUnlimitedRedeliveries pins that an unbounded consumer
// renders a note rather than a table: it has no terminal branch, so any row count
// would be invented.
func TestMarkdownHandlesUnlimitedRedeliveries(t *testing.T) {
	t.Parallel()
	out := timingcontract.Markdown(timingcontract.Contract{
		Name:     "unbounded",
		Schedule: jsconsumer.Schedule{NakDelay: time.Second, MaxDeliver: jsconsumer.UnlimitedMaxDeliver},
	})
	if strings.Contains(out, "| delivery |") {
		t.Errorf("unlimited consumer rendered a delivery table:\n%s", out)
	}
	if !strings.Contains(out, "unlimited redeliveries") {
		t.Errorf("unlimited consumer did not render its note:\n%s", out)
	}
}

// flat builds an n-rung ladder of equal delays. JetStream repeats the last rung
// once the array runs out, so a shorter list would behave identically — the rungs
// are written out so len(BackOff) is one of the three MaxDeliver numbers a
// reviewer can check against the other two.
func flat(d time.Duration, n int) []time.Duration {
	out := make([]time.Duration, n)
	for i := range out {
		out[i] = d
	}
	return out
}

