// Connect dials s and closes the connection when the test ends. Async errors are
// collected rather than written to stderr, and returned by the drain func: a
// permissions violation on $JS.ACK arrives ONLY on the async handler, so a test
// that never reads them cannot tell a denied ack from a successful one.
//
// A caller may still pass its own [nats.ErrorHandler] in opts; it is chained, not
// replaced. Both run for every async error, the collector first.
func Connect(t *testing.T, s *natsserver.Server, opts ...nats.Option) (nc *nats.Conn, asyncErrs func() []error) {
	t.Helper()
	var mu sync.Mutex
	var errs []error

	// nats.ErrorHandler assigns Options.AsyncErrorCB, so options are
	// last-one-wins and appending the collector below would silently drop a
	// handler the caller passed — losing exactly the signal this func exists to
	// surface, with nothing said about it. Probe for one and chain instead.
	//
	// The probe applies each option to a throwaway Options only to read that one
	// field. nats.Option implementations are field setters, so applying them here
	// and again inside nats.Connect is safe; an option that reports an error
	// fails the test rather than being swallowed.
	var probe nats.Options
	for i, opt := range opts {
