// Each option is evaluated EXACTLY ONCE, against defaulted options, and the
// connection is made through those — mirroring nats.Connect's own sequence
// (GetDefaultOptions → Servers → apply → Options.Connect).
//
// The obvious alternative is wrong: probing the caller's options into a
// throwaway struct to read AsyncErrorCB, then letting nats.Connect apply them
// a second time. nats.Option is an arbitrary func, not a guaranteed field
// setter — the official TLS options read files and build tls.Configs when
// applied — so a second evaluation is neither free nor certain to be
// idempotent, and a zero-value target is not the state production hands them.
o := nats.GetDefaultOptions()
o.Servers = []string{s.ClientURL()}
for i, opt := range opts {
	if opt == nil {
		continue // nats.Connect tolerates a nil option; match it
	}
	if err := opt(&o); err != nil {
		t.Fatalf("natstest: nats option %d is invalid: %v", i, err)
	}
}

// Wrap rather than replace. Assigning AsyncErrorCB here would silently drop a
// handler the caller supplied — losing exactly the signal this func exists to
// surface, with nothing said about it.
callerHandler := o.AsyncErrorCB
o.AsyncErrorCB = func(c *nats.Conn, sub *nats.Subscription, err error) {
	mu.Lock()
	errs = append(errs, err)
	mu.Unlock()
	if callerHandler != nil {
		callerHandler(c, sub, err)
	}
}

