// TestMarkdownMixesBoundedAndUnboundedHonestly is the mixed-comparison regression
// test. It is the realistic migration shape rather than a contrived one: an
// unbounded legacy loop replaced by a bounded one is exactly what trails-fanout
// went through (its `MaxDeliver -1` was retired as a fleet-wide hazard — an
// unreachable destination Nak'd forever and pinned the shared interest stream for
// every consumer on it), so a before/after table will be asked for in that shape.
//
// The bug it pins: an unbounded contract's DeadLetterDelivery is MaxDeliver less
// the capture reserve, i.e. NEGATIVE, and its TimeToDeadLetter is a cumulative
// wait to that non-existent delivery, i.e. zero. Rendered beside a bounded
// contract, that produced a column of timings and the summary "gives up on
// delivery -1 at 0s" — a fabricated terminal schedule presented as migration
// evidence.
func TestMarkdownMixesBoundedAndUnboundedHonestly(t *testing.T) {
	t.Parallel()
	before := timingcontract.Contract{
		Name:     "before (unbounded legacy)",
		Schedule: jsconsumer.Schedule{NakDelay: 30 * time.Second, MaxDeliver: jsconsumer.UnlimitedMaxDeliver},
	}
	after := timingcontract.Contract{
		Name: "after (bounded)",
		Schedule: jsconsumer.Schedule{
			ServerBackOff: []time.Duration{30 * time.Second},
			MaxDeliver:    8,
			AckWait:       30 * time.Second,
		},
	}
	if !before.Unbounded() {
		t.Fatal("the before contract should report as unbounded")
	}
	if after.Unbounded() {
		t.Fatal("the after contract should not report as unbounded")
	}

	out := timingcontract.Markdown(before, after)
	t.Logf("rendered mixed contract:\n%s", out)

	// The bounded side still tables.
	if !strings.Contains(out, "| delivery |") {
		t.Errorf("the bounded contract lost its table in a mixed comparison:\n%s", out)
	}
	if !strings.Contains(out, "t+3m30s — give up") {
		t.Errorf("the bounded contract's give-up row is missing:\n%s", out)
	}
	// The unbounded side gets a note, not a column.
	if !strings.Contains(out, "unlimited redeliveries") {
		t.Errorf("the unbounded contract did not render its note:\n%s", out)
	}
	header := strings.SplitN(out, "\n", 2)[0]
	if strings.Contains(header, before.Name) {
		t.Errorf("the unbounded contract was given a table column: %s", header)
	}
	// And nothing anywhere claims a terminal delivery it does not have.
	for _, forbidden := range []string{"delivery -1", "-1 at"} {
		if strings.Contains(out, forbidden) {
			t.Errorf("rendered output invents a terminal schedule (%q):\n%s", forbidden, out)
		}
	}
}

