// Lifecycle fan consumer: a SEPARATE durable on the LOCAL
// resource_lifecycle_v1 stream that re-publishes every event into each remote
// region's copy of the stream, subject + payload verbatim. It is a dumb
// cross-region pipe — no transformation, no GitHub fetch — so it shares the
// github_meta consumer's ack discipline but not its dispatcher. The stream is
// provisioned in fleet; if it isn't present yet the consumer logs + retries.
lifecycleDurableName := os.Getenv("META_FANOUT_LIFECYCLE_DURABLE")
if lifecycleDurableName == "" {
	lifecycleDurableName = lifecycleDurable
}
lifecycleCons := &lifecycleConsumer{
	js:      js,
	fanout:  &lifecycleFanout{remotes: lifecycleRemotes, localClusterID: localClusterID},
	metrics: metrics,
	durable: lifecycleDurableName,
	subject: lifecycleSubjectFilter,
}
