// so the new mirror's display metadata is seeded automatically. Publishes
// onto the dedicated, US-only github_meta_backfill stream the `meta-fanout
// backfill` subcommand and the backfill consumer use; the resolver re-queries
// entire-core for the mirror's owner/repo (the lifecycle event carries only
// the ULID). Best-effort — see maybeSeedMirrorMeta — so it never regresses
// the cross-region fan. Wired only in US/default mode: in lifecycle-only mode
// that stream doesn't exist, so we leave enqueuer + resolver nil and
// maybeSeedMirrorMeta cleanly no-ops (no enqueue, no "no response from
// stream" error).
if !lifecycleOnly {
	lifecycleCons.enqueuer = &backfillPublisher{js: js}
	lifecycleCons.resolver = resolver
}
lifecycleDone := make(chan struct{})
go func() {
	defer close(lifecycleDone)
	lifecycleCons.run(ctx)
