// TestLifecycle_PartialRegionFailure_LeavesDeliveryUnsettled: one unreachable
// region must not stop the others, and the delivery must be left UNSETTLED so the
// server's ladder brings the whole event back and retries it everywhere.
//
// This is where loop 1's disposition change is pinned (COR-1254). Before the
// migration a partial failure called NakWithDelay(consumerFailureDelay); now it
// calls nothing at all, because the durable carries the ladder and a client-side
// Nak beside it is the ENT-1535 defect — the server stretches each NAK delay by
// the BackOff increments, so redeliveries follow neither schedule. A plain Nak
// would be worse still: immediate redelivery, skipping the ladder entirely.
//
// "Called nothing" is a weak assertion on its own, so the cadence a reader
// actually cares about is asserted separately, from the schedule.
func TestLifecycle_PartialRegionFailure_LeavesDeliveryUnsettled(t *testing.T) {
	healthy := &recordingJS{}
	broken := &recordingJS{err: errors.New("region down")}
	c := fanoutForTest(map[string]metajobs.JetStreamPublisher{"eu": healthy, "au": broken})

	msg := &natsmsgtest.FakeMsg{}
	driveLifecycle(t, c, lifecycleTestSubject, []byte(lifecycleBody), msgIDHeader("evt-1"), msg)

	if msg.Acked || msg.Termed || nakCount(msg) != 0 {
		t.Fatalf("a partial failure must leave the delivery unsettled for the server ladder; got ack=%v nak=%d term=%v",
			msg.Acked, nakCount(msg), msg.Termed)
	}
	// The redelivery still arrives after the same flat delay it always did — the
	// owner changed, not the timing.
	if got := lifecycleSchedule().RungBefore(2); got != consumerFailureDelay {
		t.Errorf("first redelivery rung = %v, want the flat %v the client used to request", got, consumerFailureDelay)
	}
	if healthy.count() != 1 {
		t.Errorf("healthy region got %d publishes, want 1 (a failed peer must not starve it)", healthy.count())
	}
}

