package main

import (
	"testing"
	"time"

	"github.com/entirehq/mirror-pipeline/internal/timingcontract"
	"github.com/entireio/go-nuts/jsconsumer"
)

// stagingLifecycleMaxAge is the tightest retention any cell gives
// resource_lifecycle_v1: the base stream CR sets 96h, and the staging overlays
// trim it to 6h. The ladder is checked against the tight one, since a ladder that
// outlives retention never reaches its own end — the message is discarded first.
const stagingLifecycleMaxAge = 6 * time.Hour

// TestLifecycleTimingContract validates the shipped schedule and renders the
// before/after table this migration's trail carries.
//
// "Before" is the MEASURED durable, not the old constants read back: snapshots of
// all seven cells (4 prod + 3 staging) on 2026-08-14 showed no server-side
// backoff on this durable, so the effective ladder really was the client's flat
// NakWithDelay — unlike webhook-forwarder and fanout, which turned out to carry an
// undeclared 41h ladder (COR-1270). That is why loop 1 can claim an
// envelope-preserving migration and loop 2 cannot.
func TestLifecycleTimingContract(t *testing.T) {
	t.Parallel()

	before := timingcontract.Contract{
		Name: "before (client Nak, measured)",
		Schedule: jsconsumer.Schedule{
			NakDelay:     consumerFailureDelay,
			MaxDeliver:   consumerMaxDeliver,
			AckWait:      consumerAckWait,
			StreamMaxAge: stagingLifecycleMaxAge,
		},
	}
	after := timingcontract.Contract{
		Name:     "after (server ladder)",
		Schedule: lifecycleSchedule(),
	}
	after.Schedule.StreamMaxAge = stagingLifecycleMaxAge

	for _, c := range []timingcontract.Contract{before, after} {
		if err := c.Validate(); err != nil {
			t.Fatalf("%s: %v", c.Name, err)
		}
	}

	// The property loop 1 promises: the envelope does not move. Only ownership of
	// the schedule does.
	want := timingcontract.Envelope{
		DeadLetterDelivery: consumerMaxDeliver,
		TimeToDeadLetter:   time.Duration(consumerMaxDeliver-1) * consumerFailureDelay,
		LongestRung:        consumerFailureDelay,
	}
	for _, c := range []timingcontract.Contract{before, after} {
		if err := c.CheckEnvelope(want); err != nil {
			t.Error(err)
		}
	}

	t.Logf("lifecycle timing contract:\n%s", timingcontract.Markdown(before, after))
}

// TestLifecycleLadderRungsMatchMaxDeliver pins the rung count against the delivery
// cap — the first of the "three MaxDeliver numbers must agree" (ENT-1601). The
// third, a Retry's own MaxDeliver, does not exist for this consumer: it has no
// Retry, because it has no DLQ to capture into.
//
// The server rejects len(BackOff) > MaxDeliver outright, so getting this wrong is
// a startup failure rather than a silent one; the test exists so the derivation in
// lifecycleBackOff cannot be replaced by a hand-written list that drifts.
func TestLifecycleLadderRungsMatchMaxDeliver(t *testing.T) {
	t.Parallel()
	rungs := lifecycleBackOff()
	if len(rungs) != consumerMaxDeliver-1 {
		t.Errorf("ladder has %d rungs for MaxDeliver %d; want %d — one per redelivery",
			len(rungs), consumerMaxDeliver, consumerMaxDeliver-1)
	}
	for i, d := range rungs {
		if d != consumerFailureDelay {
			t.Errorf("rung %d = %v, want the flat %v", i, d, consumerFailureDelay)
		}
	}
	// AckWait must equal the first rung or the server stores the rung in its place
	// and the declared AckWait never runs (measured in
	// natstest.REDACTED).
	if consumerAckWait != rungs[0] {
		t.Errorf("AckWait %v disagrees with BackOff[0] %v", consumerAckWait, rungs[0])
	}
}

