// durableReachable reports whether the durable answers on the server. A bounded
// timeout of its own, so a probe cannot hang past the interval and stall the
// readiness signal at a stale value.
func (c *lifecycleConsumer) durableReachable(ctx context.Context, js jetstream.JetStream, cfg jsconsumer.Config) bool {
	ctx, cancel := context.WithTimeout(ctx, lifecycleReadyProbeTimeout)
	defer cancel()
	if _, err := js.Consumer(ctx, cfg.Stream, cfg.Durable); err != nil {
		// Debug, not warn: during a rollout or a provisioning race this is the
		// expected transient, and Run already logs the same condition per attempt.
		// The signal an operator acts on is /readyz itself.
		slog.DebugContext(ctx, "Lifecycle readiness probe failed; reporting NotReady",
			slog.String("stream", cfg.Stream), slog.String("durable", cfg.Durable), slog.Any("error", err))
		return false
	}
	return true
}

