// durableReachable reports whether the durable answers on the server, and routes
// the outcome through natslog.Health. A bounded timeout of its own, so a probe
// cannot hang past the interval and stall the readiness signal at a stale value.
//
// Health is what restores the supervision the hand-rolled loop had and
// jsconsumer.Run does not provide: Run logs every retryable failure at WARN
// forever, with no counter and no escalation, so a sustained outage looked exactly
// like deploy churn. Routing the probe through Health brings back both halves —
// the nats.consumer.recoverable_failures counter (restart-proof, for the
// pods-cycling-faster-than-escalation case) and the return to ERROR level after
// five minutes without recovery.
//
// This matters most where /readyz cannot help. In US/default mode the readiness
// gate deliberately excludes this consumer, so that a problem here cannot stall
// the live github_meta fan-out — which means a stopped lifecycle fan in US shows up
// ONLY in telemetry. The probe is the signal; Health is what makes it page.
func (c *lifecycleConsumer) durableReachable(ctx context.Context, js jetstream.JetStream, cfg jsconsumer.Config) bool {
	probeCtx, cancel := context.WithTimeout(ctx, lifecycleReadyProbeTimeout)
	defer cancel()
	if _, err := js.Consumer(probeCtx, cfg.Stream, cfg.Durable); err != nil {
		// SubscribeErr, not Err: this is the create/bind path, which absorbs two
		// failures a fetch path must not — a JetStream API slow to answer, and the
		// stream not existing yet (rollout ordering, kept at warn however long it
		// lasts and excluded from escalation).
		c.health.SubscribeErr(ctx, "Lifecycle durable unreachable; reporting NotReady", err,
			slog.String("stream", cfg.Stream), slog.String("durable", cfg.Durable))
		return false
	}
	c.health.Recovered()
	return true
}

