// stubClock replaces the package clock for escalation tests and restores it
// on cleanup. Tests here mutate process-global state (the clock, the default
// logger), so none of them may run parallel.
func stubClock(t *testing.T, start time.Time) *time.Time {
	t.Helper()
	clock := start
	prev := now
	now = func() time.Time { return clock }
	t.Cleanup(func() { now = prev })
	return &clock
}

