	// Two cadences, for two different situations. At startup the probe races
	// jsconsumer.Run creating the durable, so the first attempt legitimately fails
	// and a single slow interval would leave a healthy pod NotReady for seconds
	// after it was already consuming.
	//
	// The fast phase is bounded by ATTEMPTS as well as by success. Bounding it on
	// success alone was wrong: a pod that starts while the stream or the JetStream
	// API is unavailable never succeeds, so it would sit at four ConsumerInfo
	// requests and four log lines per second indefinitely — recreating the
	// log-volume problem natslog exists to solve, and contradicting the very
	// comment that said a long outage would not be hammered.
	fast := lifecycleReadyProbeStartupAttempts
	interval := lifecycleReadyProbeStartupInterval
	ticker := time.NewTicker(interval)
	defer ticker.Stop()
	for {
		bound := c.durableReachable(ctx, js, cfg)
		c.durableBound.Store(bound)
		if bound {
			// First success ends the startup race for good: a durable that
			// disappears later is a different event, and re-entering the fast phase
			// would hammer the server exactly when it is least able to answer.
			c.everBound.Store(true)
		}
		if fast > 0 {
			fast--
		}
		if steady := bound || fast == 0; steady && interval != lifecycleReadyProbeInterval {
			interval = lifecycleReadyProbeInterval
			ticker.Reset(interval)
		}
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
		}
	}
