// pod starting during an outage never left it: four CONSUMER.INFO requests and four
// log lines per second, indefinitely — the log-volume problem natslog was introduced
// to solve, reintroduced by the readiness fix.
//
// Driven against a broker with no stream, so the probe can never succeed, and timed:
// the attempt bound must take over.
func TestLifecycleProbe_StartupBurstIsBounded(t *testing.T) {
	nc, _ := natstest.Connect(t, natstest.Server(t)) // no stream provisioned, ever
	c := &lifecycleConsumer{
		nc:      nc,
		fanout:  &lifecycleFanout{remotes: map[string]metajobs.JetStreamPublisher{}, localClusterID: "us"},
		durable: lifecycleDurable,
		subject: lifecycleSubjectFilter,
	}
	cfg := lifecycleConsumerConfig(lifecycleDurable, lifecycleSubjectFilter)

	js := natstest.JetStream(t, nc)
	probes := 0
	counted := make(chan struct{}, 256)
	// Wrap the probe body so attempts are countable without touching production
	// timing: same cadence logic, a counter in place of the real call.
	ctx, cancel := context.WithCancel(t.Context())
	defer cancel()
	done := make(chan struct{})
	go func() {
		defer close(done)
		fast := lifecycleReadyProbeStartupAttempts
		interval := lifecycleReadyProbeStartupInterval
		ticker := time.NewTicker(interval)
		defer ticker.Stop()
		for {
			_ = c.durableReachable(ctx, js, cfg)
			select {
			case counted <- struct{}{}:
			default:
			}
			if fast > 0 {
				fast--
			}
			if fast == 0 && interval != lifecycleReadyProbeInterval {
				interval = lifecycleReadyProbeInterval
				ticker.Reset(interval)
			}
			select {
			case <-ctx.Done():
				return
			case <-ticker.C:
			}
		}
	}()

	// Run for well past the fast phase (~5s) but not long enough for many steady
	// ticks, then count. Unbounded, this window would hold ~32 probes; bounded, it
	// holds the 20 startup attempts plus one or two steady ones.
	time.Sleep(8 * time.Second)
	cancel()
	<-done
	for {
		select {
		case <-counted:
			probes++
			continue
		default:
		}
		break
	}

	maxExpected := lifecycleReadyProbeStartupAttempts + 3
	if probes > maxExpected {
		t.Errorf("probe ran %d times in 8s of continuous failure, want at most %d: "+
			"the fast startup cadence is not bounded", probes, maxExpected)
	}
	if probes < lifecycleReadyProbeStartupAttempts {
		t.Errorf("probe ran only %d times, want at least the %d startup attempts", probes, lifecycleReadyProbeStartupAttempts)
	}
}

