func (c *lifecycleConsumer) durableReachable(ctx context.Context, js jetstream.JetStream, cfg jsconsumer.Config, inStartupGrace bool) bool {
	probeCtx, cancel := context.WithTimeout(ctx, lifecycleReadyProbeTimeout)
	defer cancel()
	if _, err := js.Consumer(probeCtx, cfg.Stream, cfg.Durable); err != nil {
		// A missing durable means different things at different times, and only the
		// probe loop knows which — hence inStartupGrace rather than a judgement from
		// the error value.
		//
		// Inside the grace it is the startup race with jsconsumer.Run creating the
		// durable: expected, Run logs its own attempts, and reporting it through
		// Health would manufacture a failure run out of normal boot.
		//
		// Outside the grace it is one of two real problems, both loud: the durable
		// never got created (creation failing while INFO answers not-found), or it
		// disappeared after binding — which natslog keeps loud on purpose, because
		// the supervisor recreates it from the stream's DeliverPolicy (all), losing
		// the cursor and re-fanning whatever resource_lifecycle_v1 still retains, up
		// to 96h in prod. The was_bound attribute tells the two apart in the log;
		// the severity is the same because both need somebody to look.
		//
		// Honest limit: at a 5s cadence this probe can miss a delete that Run
		// recreates before the next tick, so it is a backstop rather than a
		// detector. The reliable signal is the runner's own recreate, which
		// jsconsumer only logs — recorded with the other go-nuts follow-ups this
		// migration accumulated.
		if inStartupGrace && isDurableMissing(err) {
			slog.DebugContext(ctx, "Lifecycle durable not created yet; reporting NotReady",
				slog.String("stream", cfg.Stream), slog.String("durable", cfg.Durable), slog.Any("error", err))
			return false
		}

	everBound atomic.Bool

	// probeStartupAttempts overrides lifecycleReadyProbeStartupAttempts. Zero uses
	// the constant; a test shrinks it so the never-created-after-the-budget path
	// can be driven in milliseconds rather than the five seconds the shipped value
	// takes. The only knob of its kind here, and it exists because that path is the
	// one a manual everBound in a test cannot reach.
	probeStartupAttempts int
}

// startupProbeAttempts is the startup budget in force: the override when set,
// otherwise the shipped constant.
func (c *lifecycleConsumer) startupProbeAttempts() int {
	if c.probeStartupAttempts > 0 {
		return c.probeStartupAttempts
	}
	return lifecycleReadyProbeStartupAttempts
}

