// probeCadence owns the interval between readiness probes, as a state machine
// rather than a calculation, because the property that matters is about a SEQUENCE:
// the fast startup phase must never resume once it has ended.
//
// A previous version computed the interval from the outcome and a raw
// attempts-remaining counter. That satisfied every single-call assertion and still
// broke the property: a success left the counter untouched, so a durable that bound
// on its first probe kept ~19 unspent attempts, and a genuine post-bind loss inside
// the following minute or two re-entered the 250ms cadence — hammering the server at
// exactly the moment it was least able to answer, which is what the phase is
// bounded to prevent. Ending the phase means ZEROING the budget, not decrementing
// past it, and only a type that remembers can be asked whether it did.
type probeCadence struct{ startupLeft int }

func newProbeCadence(startupAttempts int) *probeCadence {
	return &probeCadence{startupLeft: startupAttempts}
}

// startupPending reports whether startup attempts remain — i.e. whether a missing
// durable is still the expected startup race rather than a real absence.
func (p *probeCadence) startupPending() bool { return p.startupLeft > 0 }

// observe records a probe's outcome and returns the wait before the next one. A
// success ends the startup phase permanently; otherwise the phase runs until its
// budget is spent.
func (p *probeCadence) observe(bound bool) time.Duration {
	if bound {
		p.startupLeft = 0
		return lifecycleReadyProbeInterval
	}
	if p.startupLeft > 0 {
		p.startupLeft--
	}
	if p.startupLeft == 0 {
		return lifecycleReadyProbeInterval
	}
	return lifecycleReadyProbeStartupInterval
}

